INSERT INTO `obat` (`id`, `nama_obat`, `kategori`, `golongan`, `gejala_keyword`, `indikasi`, `dosis`, `aturan_pakai`, `saran_sembuh`, `peringatan`, `harga`, `stok`) VALUES
(1, 'Sanmol Paracetamol 500mg (Strip 4 Tablet)', 'Demam & Nyeri', 'Obat Bebas', 'demam panas meriang sakit kepala pusing pening sakit gigi pegal linu', 'Meredakan demam serta nyeri ringan hingga sedang seperti sakit kepala dan sakit gigi.', 'Dewasa: 1 tablet, 3-4 kali sehari.', 'Dikonsumsi sesudah makan.', 'Kompres hangat di dahi/lipatan ketiak, perbanyak minum air putih minimal 2 liter sehari, dan istirahat tidur yang cukup.', 'Hati-hati penggunaan pada penderita gangguan fungsi hati.', 4500, 71),
(2, 'Panadol Biru 500mg (Blister 10 Kaplet)', 'Demam & Nyeri', 'Obat Bebas', 'demam panas tinggi sakit kepala pusing migrain nyeri otot', 'Menurunkan demam dan meredakan sakit kepala serta nyeri otot.', 'Dewasa: 1-2 kaplet, 3-4 kali sehari (Maksimal 8 kaplet/hari).', 'Diminum dengan air putih sesudah makan.', 'Istirahat di ruangan yang sejuk, gunakan pakaian tipis yang menyerap keringat, dan hindari menatap layar HP/laptop terlalu lama.', 'Jangan melebihi dosis yang dianjurkan.', 13500, 57),
(3, 'Panadol Extra Merah (Blister 10 Kaplet)', 'Demam & Nyeri', 'Obat Bebas', 'sakit kepala berat migrain sebelah pusing berdenyut nyeri gigi', 'Meredakan sakit kepala membandel, migrain, dan sakit gigi yang mengganggu aktivitas.', 'Dewasa: 1 kaplet, 3-4 kali sehari.', 'Sesudah makan.', 'Matikan lampu kamar saat istirahat, pijat lembut area pelipis, dan hindari minuman berkafein tambahan seperti kopi.', 'Mengandung kafein, hindari minum menjelang tidur malam.', 15500, 44),
(4, 'Biogesic Paracetamol 500mg (4 Tablet)', 'Demam & Nyeri', 'Obat Bebas', 'demam meriang panas badan sakit kepala nyeri haid', 'Penurun panas demam dan pereda nyeri kepala atau nyeri tubuh.', 'Dewasa: 1-2 tablet, 3-4 kali sehari.', 'Sebelum atau sesudah makan.', 'Perbanyak konsumsi air mineral atau kuah sup hangat untuk menjaga hidrasi tubuh.', 'Hentikan penggunaan jika demam lebih dari 3 hari.', 5000, 29),
(5, 'Bodrex Migra (Strip 4 Kaplet)', 'Demam & Nyeri', 'Obat Bebas', 'migrain sakit kepala sebelah berdenyut pusing tegang leher', 'Meringankan sakit kepala sebelah (migrain) yang disertai rasa berdenyut.', 'Dewasa: 1 kaplet, 3 kali sehari.', 'Sesudah makan.', 'Kompres dingin pada bagian kepala yang berdenyut dan tidur di ruangan gelap serta tenang selama 30-60 menit.', 'Hindari mengemudi jika masih merasa pusing.', 4000, 56),
(6, 'Paramex Sakit Kepala (4 Tablet)', 'Demam & Nyeri', 'Obat Bebas Terbatas', 'sakit kepala pusing berat pening sakit gigi nyeri', 'Meringankan sakit kepala dan sakit gigi.', 'Dewasa: 1 tablet, 2-3 kali sehari.', 'Sesudah makan.', 'Kurangi begadang, atur pola tidur minimal 7 jam malam ini, dan rilekskan otot bahu serta leher.', 'Dapat menyebabkan kantuk ringan.', 3500, 109),
(7, 'Oskadon SP Nyeri Otot (4 Tablet)', 'Demam & Nyeri', 'Obat Bebas Terbatas', 'pegal linu nyeri otot pinggang punggung keseleo kecapekan', 'Meredakan nyeri otot, pegal linu di pinggang dan punggung akibat aktivitas padat.', 'Dewasa: 1 tablet, 3 kali sehari.', 'Sesudah makan penuh.', 'Lakukan peregangan ringan, mandi dengan air hangat, dan hindari mengangkat beban berat sementara waktu.', 'Tidak dianjurkan untuk penderita tukak lambung akut.', 3500, 79),
(8, 'Counterpain Cream 15g', 'Demam & Nyeri', 'Obat Bebas', 'nyeri otot keseleo terkilir memar kram betis pegal bahu leher kaku', 'Krim analgesik oles untuk meredakan nyeri otot, nyeri sendi, dan keseleo.', 'Oleskan 1-3 kali sehari pada bagian yang sakit.', 'Hanya untuk pemakaian luar pada kulit yang utuh.', 'Istirahatkan bagian otot/sendi yang nyeri, hindari memijat terlalu keras pada area yang baru terkilir.', 'Jangan dioleskan pada luka terbuka atau dekat mata.', 28000, 45),
(9, 'Salonpas Koyo Pereda Nyeri (10 Lembar)', 'Demam & Nyeri', 'Obat Bebas', 'pegal linu leher kaku salah bantal bahu tegang punggung nyeri', 'Koyo tempel untuk membantu meredakan pegal otot, leher kaku, dan nyeri punggung.', 'Tempelkan pada area yang sakit maksimal selama 8 jam.', 'Bersihkan dan keringkan kulit sebelum ditempel.', 'Gunakan bantal yang menopang leher dengan nyaman dan perbaiki postur duduk saat bekerja di depan laptop.', 'Lepaskan jika timbul iritasi atau rasa panas berlebih.', 8500, 120),
(10, 'Proris Ibuprofen 200mg (10 Kaplet)', 'Demam & Nyeri', 'Obat Bebas Terbatas', 'sakit gigi gusi bengkak nyeri haid demam tinggi radang sendi', 'Anti-inflamasi untuk meredakan nyeri sakit gigi, gusi bengkak, nyeri haid, dan demam.', 'Dewasa: 1 kaplet, 3 kali sehari.', 'Wajib diminum segera sesudah makan.', 'Untuk sakit gigi: kumur dengan air garam hangat dan hindari makanan yang terlalu manis, keras, atau dingin.', 'Hati-hati bagi penderita maag/asam lambung.', 12000, 64),
(11, 'Feminax Lancar Haid (4 Tablet)', 'Demam & Nyeri', 'Obat Bebas Terbatas', 'nyeri haid kram perut menstruasi datang bulan sakit pinggang haid', 'Meredakan kram perut dan nyeri pinggang saat menstruasi (dismenore).', '1-2 tablet, 3 kali sehari saat nyeri muncul.', 'Sesudah makan.', 'Kompres perut bagian bawah dengan botol berisi air hangat dan minum teh chamomile atau jahe hangat.', 'Jangan dikonsumsi melebihi dosis harian.', 4500, 70),
(12, 'Cataflam Fast 25mg (Eceran/Per Strip)', 'Demam & Nyeri', 'Obat Keras (Konsultasi)', 'sakit gigi parah nyeri akut radang gusi bengkak pasca cabut gigi', 'Pereda nyeri reaksi cepat untuk sakit gigi akut dan peradangan.', 'Dewasa: 1 tablet, 2 kali sehari bila nyeri hebat.', 'Sesudah makan penuh.', 'Kompres pipi yang bengkak dengan es batu yang dibungkus kain selama 15 menit dan segera jadwalkan periksa ke dokter gigi.', 'Tidak untuk penggunaan jangka panjang & penderita maag berat.', 38000, 34),
(13, 'ByeBye Fever Dewasa (1 Lembar)', 'Demam & Nyeri', 'Alat Kesehatan', 'demam panas tinggi sakit kepala kompres dahi', 'Plester kompres penurun panas praktis dengan efek dingin hingga 10 jam.', 'Tempelkan pada dahi atau pipi sesuai kebutuhan.', 'Pemakaian luar.', 'Tetap pantau suhu tubuh menggunakan termometer setiap 4 jam dan minum air putih secara berkala.', 'Hanya untuk pemakaian luar.', 12500, 50),
(14, 'Hot In Cream Tube 60g', 'Demam & Nyeri', 'Obat Bebas', 'masuk angin perut kembung pegal kaki kram otot dingin', 'Krim aromaterapi hangat untuk mengatasi capek, pegal-pegal, dan nyeri otot.', 'Oleskan secukupnya pada bagian tubuh yang pegal.', 'Pemakaian luar.', 'Gunakan kaos kaki hangat sebelum tidur agar sirkulasi darah di kaki lebih rileks.', 'Cuci tangan dengan sabun setelah mengoleskan krim.', 19500, 55),
(15, 'Sumagesic Paracetamol 600mg (4 Tablet)', 'Demam & Nyeri', 'Obat Bebas', 'sakit kepala berat demam tinggi nyeri badan meriang hebat', 'Paracetamol dosis 600mg untuk meredakan sakit kepala membandel dan demam tinggi.', 'Dewasa: 1 tablet, 3 kali sehari.', 'Sesudah makan.', 'Istirahat total dari aktivitas fisik berat dan konsumsi makanan berkuah hangat yang mudah dicerna.', 'Perhatikan jeda waktu minum minimal 6 jam antar dosis.', 4000, 94),
(16, 'OBH Combi Batuk Berdahak Menthol 100ml', 'Batuk & Flu', 'Obat Bebas Terbatas', 'batuk berdahak tenggorokan berlendir gatal dada sesak dahak susah keluar', 'Mengencerkan dahak dan meredakan batuk berdahak dengan sensasi menthol yang melegakan.', 'Dewasa: 3 kali sehari, 3 sendok takar (15 ml).', 'Sesudah makan.', 'Minum air putih hangat sesering mungkin untuk membantu mengencerkan dahak, serta hindari gorengan dan minuman dingin/es.', 'Dapat menyebabkan kantuk, jangan mengendarai kendaraan.', 19500, 89),
(17, 'OBH Combi Batuk Plus Flu Menthol 60ml', 'Batuk & Flu', 'Obat Bebas Terbatas', 'batuk flu pilek demam hidung tersumbat bersin pusing', 'Meredakan batuk yang disertai gejala flu seperti demam, sakit kepala, hidung tersumbat, dan bersin.', 'Dewasa: 3 kali sehari, 3 sendok takar (15 ml).', 'Sesudah makan.', 'Hirup uap air hangat untuk melegakan hidung tersumbat dan tidur dengan posisi bantal sedikit lebih tinggi.', 'Menyebabkan kantuk.', 16500, 80),
(18, 'Siladex Mucolytic & Expectorant 60ml (Bebas Gula)', 'Batuk & Flu', 'Obat Bebas Terbatas', 'batuk berdahak lendir kental tenggorokan mengganjal tidak bikin ngantuk', 'Mengencerkan dahak kental pada saluran pernapasan dan mempermudah pengeluaran dahak tanpa efek kantuk.', 'Dewasa: 3 kali sehari, 1 sendok takar (5 ml).', 'Sesudah makan.', 'Tepuk-tepuk lembut punggung saat batuk untuk membantu meluruhkan dahak dan jauhi asap rokok maupun debu.', 'Kocok dahulu sebelum diminum.', 18000, 64),
(19, 'Siladex Antitussive Merah 60ml', 'Batuk & Flu', 'Obat Bebas Terbatas', 'batuk kering batuk tidak berdahak tenggorokan gatal batuk malam hari', 'Meredakan batuk kering tidak berdahak yang disertai rasa gatal di tenggorokan.', 'Dewasa: 3 kali sehari, 1 sendok takar (5 ml).', 'Sesudah makan.', 'Siapkan segelas air hangat di samping tempat tidur dan konsumsi 1 sendok madu murni sebelum tidur.', 'Dapat menyebabkan rasa kantuk.', 18000, 59),
(20, 'Woods Peppermint Antitussive 60ml', 'Batuk & Flu', 'Obat Bebas Terbatas', 'batuk kering gatal tenggorokan batuk terus menerus suara serak', 'Sirup pereda batuk kering dengan kandungan zat penekan batuk dan sensasi peppermint.', 'Dewasa: 3 kali sehari, 2 sendok takar (10 ml).', 'Sesudah makan.', 'Kurangi berbicara terlalu keras, hindari makanan pedas dan kerupuk/camilan kering yang mengiritasi tenggorokan.', 'Jangan digunakan melebihi dosis yang disarankan.', 24500, 50),
(21, 'Vicks Formula 44 Dewasa 54ml', 'Batuk & Flu', 'Obat Bebas Terbatas', 'batuk kering batuk berdahak bersin gatal tenggorokan susah tidur karena batuk', 'Kombinasi pereda batuk kering maupun berdahak yang membantu tidur lebih nyenyak di malam hari.', 'Dewasa: Gunakan setiap 4 jam sesuai kebutuhan (maks 6x sehari), 2 sendok takar (10 ml).', 'Sesudah makan.', 'Jaga kelembapan udara kamar (hindari AC yang terlalu dingin) dan perbanyak istirahat.', 'Dapat menyebabkan kantuk.', 23000, 55),
(22, 'Bisolvon Extra 60ml', 'Batuk & Flu', 'Obat Bebas Terbatas', 'batuk berdahak membandel lendir susah keluar dada berat', 'Bekerja ganda mengencerkan dahak kental dan mengeluarkan dahak dari saluran napas.', 'Dewasa: 3 kali sehari, 10 ml.', 'Sesudah makan.', 'Minum air jahe hangat atau lemon hangat untuk menenangkan saluran pernapasan.', 'Hati-hati pada penderita tukak lambung.', 52000, 23),
(23, 'Decolgen Flu & Batuk (Strip 4 Tablet)', 'Batuk & Flu', 'Obat Bebas Terbatas', 'flu pilek hidung tersumbat meler bersin bersin demam pusing', 'Meredakan gejala flu seperti hidung tersumbat, bersin-bersin, sakit kepala, dan demam.', 'Dewasa: 1 tablet, 3 kali sehari.', 'Sesudah makan.', 'Gunakan masker saat beraktivitas, buang tisu bekas ingus ke tempat tertutup, dan konsumsi buah tinggi vitamin C.', 'Menyebabkan kantuk.', 3500, 109),
(24, 'Neozep Forte (Strip 4 Tablet)', 'Batuk & Flu', 'Obat Bebas Terbatas', 'pilek berat hidung mampet ingusan bersin demam meriang flu', 'Mengatasi pilek, hidung tersumbat, bersin-bersin, dan pegal meriang akibat flu.', 'Dewasa: 1 tablet, 3-4 kali sehari.', 'Sesudah makan.', 'Bilas atau uapi rongga hidung dengan uap hangat dan istirahat penuh agar imun cepat pulih.', 'Menyebabkan kantuk, hindari berkendara.', 4000, 100),
(25, 'Ultraflu (Strip 4 Kaplet)', 'Batuk & Flu', 'Obat Bebas Terbatas', 'flu demam sakit kepala hidung tersumbat bersin meriang', 'Meringankan gejala flu seperti demam, sakit kepala, hidung tersumbat dan bersin-bersin.', 'Dewasa: 1 kaplet, 3 kali sehari.', 'Sesudah makan.', 'Makan sup ayam hangat dan tidur lebih awal untuk mempercepat pemulihan daya tahan tubuh.', 'Dapat menyebabkan kantuk.', 4000, 90),
(26, 'Panadol Cold & Flu Hijau (10 Kaplet)', 'Batuk & Flu', 'Obat Bebas Terbatas', 'flu hidung tersumbat batuk tidak berdahak demam tidak ngantuk', 'Meredakan hidung tersumbat, batuk kering, dan demam akibat flu dengan formula tidak menyebabkan kantuk.', 'Dewasa: 1 kaplet, 3-4 kali sehari.', 'Sesudah makan.', 'Tetap minum air putih hangat secara rutin meski sedang beraktivitas atau kuliah.', 'Tidak dianjurkan untuk penderita hipertensi.', 16500, 72),
(27, 'Degirol Hisap (Strip 10 Tablet)', 'Batuk & Flu', 'Obat Bebas', 'sakit tenggorokan radang tenggorokan susah menelan gatal tenggorokan sariawan', 'Tablet hisap antiseptik untuk meredakan sakit tenggorokan, radang mulut, dan infeksi rongga mulut.', 'Hisap 1 tablet perlahan setiap 3-4 jam (Maksimal 8 tablet sehari).', 'Dihisap seperti permen, jangan dikunyah.', 'Berkumur dengan air garam hangat 2 kali sehari dan hindari makanan berminyak serta minuman manis kemasan.', 'Hindari makan/minum selama 15 menit setelah menghisap tablet.', 15000, 73),
(28, 'FG Troches Meiji (Strip 10 Tablet)', 'Batuk & Flu', 'Obat Keras (Konsultasi)', 'radang tenggorokan parah amandel bengkak sakit menelan suara hilang', 'Tablet hisap untuk mengatasi radang tenggorokan akut dan tonsilitis (radang amandel).', 'Dewasa: 1-2 tablet dihisap, 4-5 kali sehari.', 'Dihisap perlahan sesudah makan.', 'Perbanyak minum air suhu ruang, istirahatkan pita suara, dan hindari makanan pedas atau asam.', 'Penggunaan harus sesuai petunjuk apoteker/dokter.', 22000, 59),
(29, 'Strepsils Original / Honey Lemon (8 Butir)', 'Batuk & Flu', 'Obat Bebas', 'tenggorokan kering gatal serak batuk ringan', 'Permen hisap pelega tenggorokan kering, gatal, dan suara serak.', 'Hisap 1 butir setiap 2-3 jam bila perlu.', 'Dihisap perlahan.', 'Bawa botol air minum kemana pun pergi agar tenggorokan selalu lembap.', 'Jangan diberikan pada anak di bawah 6 tahun.', 19000, 70),
(30, 'Vicks Inhaler Pelega Hidung', 'Batuk & Flu', 'Obat Bebas', 'hidung tersumbat mampet susah napas karena pilek flu', 'Inhaler praktis dengan uap menthol dan camphor untuk melegakan hidung tersumbat seketika.', 'Hirup uap melalui tiap lubang hidung saat terasa tersumbat.', 'Pemakaian luar (hirup).', 'Kombinasikan dengan minum air hangat dan oleskan balsem hangat di area dada/leher.', 'Gunakan secara pribadi, jangan bergantian dengan orang lain.', 21000, 65),
(31, 'Promag Tablet Kunyah (Blister 12 Tablet)', 'Pencernaan & Lambung', 'Obat Bebas', 'maag asam lambung naik perih ulu hati mual kembung begah sering sendawa', 'Menetralkan asam lambung dengan cepat, meredakan nyeri ulu hati, mual, dan perut kembung.', 'Dewasa: 1-2 tablet dikunyah, 3-4 kali sehari.', 'Dikunyah halus 1 jam sebelum makan atau 2 jam sesudah makan dan menjelang tidur.', 'Makan dalam porsi kecil tapi sering (setiap 3-4 jam), hindari kopi, cokelat, makanan pedas, asam, dan jangan langsung rebahan setelah makan.', 'Beri jeda 2 jam jika sedang mengonsumsi obat lain.', 9500, 118),
(32, 'Mylanta Sirup 50ml', 'Pencernaan & Lambung', 'Obat Bebas', 'maag akut asam lambung naik ke dada gerd panas dada perih lambung mual', 'Sirup antasida cair yang bekerja cepat melapisi dinding lambung dan meredakan perih ulu hati serta kembung.', 'Dewasa: 1-2 sendok takar (5-10 ml), 3-4 kali sehari.', 'Diminum 1 jam sebelum makan atau 2 jam sesudah makan.', 'Tidur dengan posisi kepala dan dada lebih tinggi (gunakan 2 bantal) untuk mencegah asam lambung naik ke kerongkongan.', 'Kocok botol sebelum diminum.', 19500, 74),
(33, 'Polysilane Suspensi 100ml', 'Pencernaan & Lambung', 'Obat Bebas', 'perut kembung penuh gas begah maag mual nyeri lambung', 'Mengatasi kelebihan asam lambung, gastritis, tukak lambung, serta mengurangi gas berlebih di perut.', 'Dewasa: 1-2 sendok takar (5-10 ml), 3-4 kali sehari.', 'Sebelum makan dan menjelang tidur malam.', 'Konsumsi makanan lembut seperti bubur, pisang, atau kentang rebus, dan kunyah makanan secara perlahan.', 'Simpan di tempat sejuk.', 31000, 49),
(34, 'Sanmag Suspensi 120ml', 'Pencernaan & Lambung', 'Obat Bebas', 'nyeri lambung maag kembung mual muntah ulu hati melilit', 'Meredakan gejala kelebihan asam lambung, gastritis, dan perut kembung.', 'Dewasa: 1-2 sendok takar (5-10 ml), 3-4 kali sehari.', '1 jam sebelum makan.', 'Kelola stres dengan baik karena kecemasan dapat memicu produksi asam lambung berlebih.', 'Jangan digunakan terus-menerus lebih dari 2 minggu.', 37000, 14),
(35, 'Antasida Doen Tablet Kunyah (10 Tablet)', 'Pencernaan & Lambung', 'Obat Bebas', 'maag asam lambung perih perut kosong mual kembung', 'Obat generik penurun asam lambung untuk meredakan mual, nyeri lambung, dan nyeri ulu hati.', 'Dewasa: 1-2 tablet dikunyah, 3-4 kali sehari.', 'Dikunyah sebelum makan.', 'Jangan pernah melewatkan sarapan pagi dan siapkan biskuit gandum untuk camilan pengganjal perut.', 'Kunyah tablet hingga benar-benar halus sebelum ditelan.', 3500, 122),
(36, 'Diapet Kapsul (Strip 10 Kapsul)', 'Pencernaan & Lambung', 'Obat Herbal Terstandar', 'diare mencret bab cair perut mulas melilit sakit perut', 'Ekstrak daun jambu biji dan kunyit untuk memadatkan feses dan mengurangi frekuensi buang air besar.', 'Dewasa: 2 kapsul, 2 kali sehari. Untuk diare akut: 2 kapsul, 2 kali dengan selang 1 jam.', 'Sesudah makan.', 'Wajib mengganti cairan tubuh yang hilang dengan minum oralit atau air putih setiap kali selesai BAB, serta makan nasi putih dan pisang.', 'Jika diare disertai darah atau demam tinggi, segera ke dokter.', 6500, 100),
(37, 'Entrostop Herbal / Tablet (Strip 12 Tablet)', 'Pencernaan & Lambung', 'Obat Bebas', 'diare mencret keracunan makanan salah makan perut mulas bab terus', 'Menyerap racun dan bakteri penyebab diare di saluran pencernaan serta memadatkan feses.', 'Dewasa: 2 tablet setiap selesai buang air besar (Maksimal 12 tablet sehari).', 'Diminum setiap habis BAB cair.', 'Hindari susu, santan, makanan pedas, dan makanan berserat tinggi (sayuran mentah) selama masih diare.', 'Beri jarak 2-3 jam dengan obat lain karena dapat menyerap obat lain.', 10500, 93),
(38, 'New Diatabs (Strip 4 Tablet)', 'Pencernaan & Lambung', 'Obat Bebas', 'diare akut mencret bab berair sakit perut melilit', 'Mengandung Attapulgite aktif untuk memperlambat gerakan usus yang terlalu cepat dan mengikat racun diare.', 'Dewasa: 2 tablet setiap setelah buang air besar (Maksimal 12 tablet/24 jam).', 'Sesudah BAB.', 'Perbanyak istirahat dan minum cairan elektrolit agar tubuh tidak lemas atau dehidrasi.', 'Hentikan pemakaian jika diare sudah berhenti.', 3500, 110),
(39, 'Oralit 200 Sachet (Garam Elektrolit)', 'Pencernaan & Lambung', 'Obat Bebas', 'dehidrasi lemas karena diare muntah muntah kurang cairan haus terus', 'Larutan rehidrasi oral untuk mencegah dan mengatasi dehidrasi akibat diare atau muntah.', 'Larutkan 1 sachet ke dalam 200 ml air matang, minum setiap habis BAB/muntah.', 'Diminum sedikit demi sedikit tapi sering.', 'Gunakan air matang suhu ruang (bukan air mendidih) saat melarutkan oralit.', 'Larutan yang sudah dibuat tidak boleh disimpan lebih dari 24 jam.', 2000, 200),
(40, 'L-Bio Probiotik (Per Sachet)', 'Pencernaan & Lambung', 'Suplemen Kesehatan', 'pencernaan terganggu diare kembung pemulihan usus sembelit anak dewasa', 'Bakteri baik (probiotik) untuk menyeimbangkan flora normal usus saat mengalami diare atau gangguan cerna.', 'Dewasa: 1 sachet, 2-3 kali sehari.', 'Dapat dikonsumsi langsung atau dicampur makanan/air dingin.', 'Konsumsi secara rutin selama 3-5 hari untuk mengembalikan kesehatan saluran cerna secara optimal.', 'Jangan dicampur dengan air panas atau minuman bersoda.', 11000, 80),
(41, 'Dulcolax Tablet 5mg (Blister 4 Tablet)', 'Pencernaan & Lambung', 'Obat Bebas Terbatas', 'sembelit susah bab konstipasi perut begah belum bab berhari hari', 'Obat pencahar yang merangsang pergerakan usus besar agar buang air besar lancar keesokan paginya.', 'Dewasa: 1-2 tablet diminum sekaligus pada malam hari.', 'Diminum malam sebelum tidur, ditelan utuh (jangan dikunyah).', 'Perbanyak makan buah pepaya, sayur hijau, minum air putih hangat saat bangun tidur, dan lakukan jalan kaki ringan.', 'Jangan diminum bersamaan dengan susu atau obat maag (antasida).', 11500, 70),
(42, 'Microlax Gel Enema 5ml', 'Pencernaan & Lambung', 'Obat Bebas', 'sembelit keras susah bab feses keras konstipasi akut', 'Pencahar bentuk gel yang bekerja cepat dalam 15-30 menit dengan melunakkan feses tanpa rasa mulas.', '1 tube digunakan melalui rektum (anus) saat dibutuhkan.', 'Pemakaian rektal.', 'Jangan menahan keinginan BAB saat sinyal tubuh muncul dan tingkatkan asupan serat harian.', 'Hanya untuk penggunaan sesekali saat sembelit akut.', 27500, 45),
(43, 'Vegeta Herbal (Per Sachet)', 'Pencernaan & Lambung', 'Suplemen Serat', 'susah bab kurang serat perut buncit begah sembelit ringan', 'Minuman suplemen serat alami untuk membantu melancarkan buang air besar.', '1 sachet dilarutkan dalam segelas air dingin, diminum 1 kali sehari sebelum tidur.', 'Sesudah makan malam.', 'Imbangi dengan minum minimal 8 gelas air putih sehari agar serat bekerja optimal di usus.', 'Tidak dianjurkan untuk anak-anak.', 3500, 90),
(44, 'Antimo 50mg (Strip 10 Tablet)', 'Pencernaan & Lambung', 'Obat Bebas Terbatas', 'mabuk perjalanan mual muntah pusing berputar vertigo kendaraan laut darat', 'Mencegah dan mengatasi mual, muntah, serta pusing akibat mabuk perjalanan.', 'Dewasa: 1 tablet diminum 30 menit sebelum perjalanan (bila perlu diulang tiap 4 jam).', 'Sesudah makan ringan.', 'Duduk menghadap ke depan, pandang objek jauh di cakrawala, jangan bermain HP di dalam kendaraan yang bergerak.', 'Menyebabkan kantuk kuat.', 6000, 100),
(45, 'Tolak Angin Cair Madu (Per Sachet)', 'Pencernaan & Lambung', 'Obat Herbal Terstandar', 'masuk angin perut kembung mual meriang pusing kecapekan perjalanan jauh', 'Herbal terstandar dari jahe, daun mint, adas, dan madu untuk mengatasi masuk angin, mual, dan kembung.', '1 sachet langsung diminum atau dicampur setengah gelas air hangat, 2-3 kali sehari.', 'Sesudah makan.', 'Gunakan jaket hangat, minum teh hangat, dan istirahat tidur lebih awal.', 'Tidak dianjurkan bagi ibu hamil.', 4500, 150),
(46, 'CTM (Chlorpheniramine Maleate) 4mg (12 Tablet)', 'Alergi & Kulit', 'Obat Bebas Terbatas', 'alergi gatal gatal biduran kaligata bersin alergi dingin debu bentol merah', 'Antihistamin untuk meredakan gejala alergi seperti gatal-gatal pada kulit, biduran, dan bersin akibat alergi.', 'Dewasa: 1 tablet, 3-4 kali sehari.', 'Sesudah makan.', 'Hindari menggaruk kulit yang gatal agar tidak luka, mandi dengan air sejuk, dan gunakan pakaian longgar berbahan katun.', 'Menyebabkan kantuk berat, dilarang mengemudi setelah minum.', 3000, 120),
(47, 'Incidal-OD Cetirizine 10mg (Strip 4 Kapsul)', 'Alergi & Kulit', 'Obat Bebas Terbatas', 'alergi gatal biduran alergi makanan seafood dingin bersin pagi hari rhinitis', 'Obat alergi generasi kedua yang bekerja 24 jam meredakan biduran, gatal alergi, dan pilek alergi.', 'Dewasa: 1 kapsul, cukup 1 kali sehari.', 'Malam hari sebelum tidur atau sesudah makan.', 'Catat dan hindari pemicu alergi (seperti debu kamar, udara terlalu dingin, atau makanan laut tertentu).', 'Dapat menyebabkan kantuk ringan pada sebagian orang.', 21000, 65),
(48, 'Cetirizine Generik 10mg (Strip 10 Tablet)', 'Alergi & Kulit', 'Obat Bebas Terbatas', 'alergi kulit gatal bentol biduran merah bersin gatal hidung mata berair', 'Meredakan gejala alergi kulit (urtikaria/biduran) dan rhinitis alergi.', 'Dewasa: 1 tablet, 1 kali sehari.', 'Sebelum atau sesudah makan.', 'Oleskan losion calamine pada kulit yang bentol untuk memberi efek sejuk dan mengurangi keinginan menggaruk.', 'Hati-hati pada penderita gangguan ginjal.', 7500, 90),
(49, 'Caladine Lotion 60ml', 'Alergi & Kulit', 'Obat Bebas', 'gatal biang keringat alergi kulit gigitan serangga nyamuk bentol panas kulit', 'Losion penyejuk kulit yang mengandung Calamine dan Zinc Oxide untuk mengatasi gatal akibat biang keringat, udara panas, dan gigitan serangga.', 'Oleskan 2-4 kali sehari pada kulit yang gatal.', 'Sebaiknya digunakan sehabis mandi pagi dan sore.', 'Jaga kulit tetap kering dan bersih dari keringat, serta ganti baju segera jika basah oleh keringat.', 'Jangan dioleskan pada luka terbuka atau melepuh.', 21500, 60),
(50, 'Bedak Salicyl Kimia Farma 60g', 'Alergi & Kulit', 'Obat Bebas', 'biang keringat gatal punggung alergi keringat kulit lembap gatal', 'Bedak tabur antiseptik untuk mengurangi gatal-gatal akibat biang keringat dan gangguan kulit ringan.', 'Taburkan dan usapkan pada bagian kulit yang gatal sehabis mandi.', 'Pemakaian luar.', 'Keringkan badan dengan handuk bersih secara ditepuk-tepuk sebelum menaburkan bedak.', 'Jangan digunakan pada anak di bawah 3 tahun.', 9500, 75),
(51, 'Kalpanax Krim 5g', 'Alergi & Kulit', 'Obat Bebas', 'jamur kulit panu kadas kurap kutu air gatal sela jari kaki selangkangan', 'Krim antijamur dengan Miconazole untuk membasmi jamur kulit penyebab panu, kadas, kurap, dan kutu air.', 'Oleskan tipis pada kulit yang terinfeksi jamur 2 kali sehari selama 2 minggu.', 'Sehabis mandi saat kulit sudah kering.', 'Jangan berbagi handuk atau pakaian dengan orang lain, dan jemur sepatu/kaos kaki hingga benar-benar kering.', 'Tetap lanjutkan pemakaian beberapa hari setelah gatal hilang agar jamur tuntas.', 16500, 55),
(52, 'Canesten Krim 5g (Clotrimazole)', 'Alergi & Kulit', 'Obat Bebas Terbatas', 'jamur kulit kurap panu kutu air ruam popok gatal lipatan kulit', 'Mengatasi infeksi jamur pada kulit, sela-sela jari kaki, dan lipatan tubuh.', 'Oleskan tipis 2-3 kali sehari pada area yang sakit.', 'Pemakaian luar pada kulit bersih.', 'Gunakan pakaian dalam yang menyerap keringat dan segera ganti setelah berolahraga.', 'Hindari kontak dengan mata.', 29000, 45),
(53, 'Daktarin Krim 5g', 'Alergi & Kulit', 'Obat Bebas Terbatas', 'infeksi jamur kulit kutu air gatal sela jari kurap panu', 'Krim antijamur efektif untuk menghentikan pertumbuhan jamur kulit dan menghilangkan rasa gatalnya.', 'Oleskan 2 kali sehari (pagi dan malam) selama 2-4 minggu.', 'Pemakaian luar.', 'Cuci kaki dengan sabun setiap pulang beraktivitas dan keringkan sela-sela jari kaki.', 'Hanya untuk pemakaian luar.', 28500, 40),
(54, 'Bioplacenton Gel 15g', 'Alergi & Kulit', 'Obat Keras (Konsultasi)', 'luka bakar kena knalpot air panas minyak panas luka lecet jatuh berair', 'Gel perawatan luka bakar dan luka terbuka yang membantu mencegah infeksi serta mempercepat regenerasi kulit baru.', 'Oleskan tipis pada area luka 3-5 kali sehari.', 'Bersihkan luka terlebih dahulu sebelum dioles.', 'Saat baru terkena panas, segera aliri area kulit dengan air mengalir suhu ruang selama 10-15 menit (jangan diberi odol/pasta gigi).', 'Gunakan sesuai petunjuk pada area luka.', 33000, 50),
(55, 'Betadine Antiseptic Solution 15ml', 'Alergi & Kulit', 'Obat Bebas', 'luka jatuh lecet tergores luka berdarah cegah infeksi antiseptik', 'Cairan antiseptik Povidone-Iodine 10% untuk membunuh kuman pada luka lecet, luka iris, dan luka jatuh.', 'Teteskan atau oleskan menggunakan kapas/kasa steril pada luka 1-2 kali sehari.', 'Pemakaian luar pada luka.', 'Cuci luka terlebih dahulu dari kotoran/pasir menggunakan air bersih atau cairan infus NaCl sebelum ditetesi antiseptik.', 'Hentikan jika timbul reaksi alergi yodium.', 18500, 85),
(56, 'Hansaplast Kain Elastis (Amplop 10 Lembar)', 'Alergi & Kulit', 'Alat Kesehatan', 'luka gores jari teriris pisau lecet sepatu tutup luka plester', 'Plester penutup luka elastis yang mengikuti lekuk tubuh dan melindungi luka dari kotoran serta bakteri.', 'Tempelkan pada luka yang sudah dibersihkan, ganti plester setiap hari atau jika basah.', 'Pemakaian luar.', 'Pastikan kulit di sekitar luka kering agar plester menempel sempurna.', 'Sekali pakai.', 4500, 150),
(57, 'Thrombophob Gel 20g', 'Alergi & Kulit', 'Obat Bebas Terbatas', 'memar biru bengkak terbentur jatuh keseleo darah beku bawah kulit', 'Gel pengurai gumpalan darah di bawah kulit untuk mempercepat hilangnya memar kebiruan dan bengkak akibat benturan.', 'Oleskan tipis 2-3 kali sehari pada area memar (jangan dipijat/digosok keras).', 'Pemakaian luar pada kulit yang tidak terluka.', 'Kompres dingin area yang terbentur pada 24 jam pertama untuk mengurangi pembengkakan.', 'Dilarang dioleskan pada luka terbuka yang berdarah.', 72000, 30),
(58, 'Acnes Sealing Jell 9g', 'Alergi & Kulit', 'Kosmedik', 'jerawat meradang jerawat batu bruntusan komedo wajah merah jerawat', 'Gel transparan khusus untuk merawat kulit berjerawat, melawan bakteri penyebab jerawat, dan mengangkat sel kulit mati.', 'Oleskan tipis pada titik jerawat 2-3 kali sehari.', 'Gunakan setelah mencuci wajah.', 'Jangan memencet jerawat dengan tangan kotor, ganti sarung bantal seminggu sekali, dan kurangi makanan manis/berminyak.', 'Jika kulit terasa terlalu kering, kurangi frekuensi pemakaian.', 21000, 60),
(59, 'Minyak Kayu Putih Cap Lang 60ml', 'Alergi & Kulit', 'Obat Tradisional', 'masuk angin perut kembung gatal digigit nyamuk dingin mual', 'Minyak kayu putih alami untuk memberikan rasa hangat, meredakan perut kembung, dan gatal akibat gigitan serangga.', 'Oleskan secukupnya pada perut, dada, punggung, atau area gigitan nyamuk.', 'Pemakaian luar.', 'Pijat lembut perut searah jarum jam saat kembung untuk membantu mengeluarkan gas.', 'Jangan tertelan.', 24000, 90),
(60, 'FreshCare Smash / Citrus Roll On 10ml', 'Alergi & Kulit', 'Obat Luar', 'pusing mual mabuk perjalanan pegal leher gatal nyamuk hidung mampet', 'Minyak angin aromaterapi kemas roll-on praktis untuk meredakan pusing, perut kembung, dan gatal serangga.', 'Oleskan pada kening, dada, leher, atau hidung sesuai kebutuhan.', 'Pemakaian luar.', 'Tarik napas dalam-dalam sambil menghirup aromaterapi untuk merelaksasi pikiran yang tegang.', 'Hindari area mata.', 14500, 110),
(61, 'Insto Regular Tetes Mata 7.5ml', 'Mata, Mulut & THT', 'Obat Bebas Terbatas', 'mata merah mata perih iritasi mata debu asap mata lelah layar laptop', 'Mengatasi mata merah dan rasa perih akibat iritasi ringan karena debu, asap, angin, atau setelah berenang.', 'Teteskan 2-3 tetes pada setiap mata, 3-4 kali sehari.', 'Teteskan pada kantung mata bagian bawah.', 'Terapkan aturan 20-20-20 saat di depan laptop (setiap 20 menit, lihat objek sejauh 20 kaki selama 20 detik) dan jangan mengucek mata.', 'Jangan digunakan saat sedang memakai lensa kontak (softlens).', 15500, 80),
(62, 'Insto Dry Eyes 7.5ml (Biru)', 'Mata, Mulut & THT', 'Obat Bebas', 'mata kering mata sepet pegal menatap layar hp komputer kurang air mata', 'Memberikan efek pelumas seperti air mata alami untuk mengatasi gejala mata kering, sepet, dan lelah.', 'Teteskan 1-2 tetes pada setiap mata, 3 kali sehari atau sesuai kebutuhan.', 'Tetes mata.', 'Sering-seringlah berkedip secara sadar saat fokus ngoding atau membaca di layar.', 'Buang kemasan 30 hari setelah segel dibuka.', 16500, 75),
(63, 'Rohto Cool Tetes Mata 7ml', 'Mata, Mulut & THT', 'Obat Bebas Terbatas', 'mata merah iritasi mata panas lelah ngantuk sensasi dingin sejuk', 'Meredakan mata merah akibat iritasi ringan dengan sensasi dingin menyegarkan.', 'Teteskan 1-2 tetes pada mata yang iritasi, 3-4 kali sehari.', 'Tetes mata.', 'Gunakan kacamata pelindung saat berkendara motor agar mata tidak terpapar debu jalanan.', 'Lepas softlens sebelum meneteskan obat.', 19000, 65),
(64, 'Cendo Lyteers Tetes Mata 15ml', 'Mata, Mulut & THT', 'Obat Bebas', 'mata kering iritasi softlens mata lelah perih aman untuk mata sensitif', 'Air mata buatan isotonik yang melembapkan mata kering dan meredakan iritasi ringan.', 'Teteskan 1-2 tetes pada masing-masing mata, 3-4 kali sehari.', 'Tetes mata.', 'Kompres mata yang lelah dengan handuk hangat selama 5 menit sebelum tidur.', 'Pastikan ujung botol tidak menyentuh bola mata atau bulu mata.', 31000, 50),
(65, 'Erlamycetin Salep Mata 3.5g', 'Mata, Mulut & THT', 'Obat Keras (Konsultasi)', 'belekan mata bengkak infeksi bakteri mata bintitan merah lengket bangun tidur', 'Salep mata untuk mengatasi infeksi bakteri permukaan mata seperti konjungtivitis (mata belekan).', 'Oleskan sedikit salep pada bagian dalam kelopak mata bawah, 3-4 kali sehari.', 'Bersihkan kotoran mata dengan kapas air hangat sebelum dioles.', 'Jangan menyentuh mata yang sehat setelah menyentuh mata yang sakit, dan pisahkan handuk wajah.', 'Pandangan mungkin sedikit buram sesaat setelah memakai salep.', 16000, 40),
(66, 'Vital Ear Oil 10ml (Tetes Telinga)', 'Mata, Mulut & THT', 'Obat Bebas', 'telinga gatal kotoran telinga keras telinga tersumbat berdengung radang telinga ringan', 'Antiseptik rongga telinga untuk melunakkan kotoran telinga yang mengeras dan meredakan gatal/iritasi liang telinga.', 'Teteskan 2 tetes ke dalam lubang telinga, 3 kali sehari.', 'Miringkan kepala beberapa menit setelah diteteskan.', 'Hindari mengorek telinga terlalu dalam menggunakan cotton bud karena dapat mendorong kotoran semakin masuk.', 'Jangan digunakan jika gendang telinga pecah/berlubang.', 18500, 45),
(67, 'Betadine Mouthwash & Gargle 190ml', 'Mata, Mulut & THT', 'Obat Bebas', 'sariawan bau mulut gusi bengkak sakit tenggorokan radang gusi kumur', 'Obat kumur antiseptik untuk mengatasi sariawan, gusi bengkak, sakit tenggorokan, dan bau mulut.', 'Tuang 15 ml pada tutup botol, kumur di mulut dan tenggorokan selama 30 detik, 3-5 kali sehari.', 'Kumur lalu buang (jangan ditelan).', 'Sikat gigi secara teratur 2 kali sehari (pagi sesudah sarapan dan malam sebelum tidur).', 'Jangan ditelan.', 39000, 50),
(68, 'Aloclair Plus Gel 8ml', 'Mata, Mulut & THT', 'Alat Kesehatan', 'sariawan perih luka mulut tergigit kawat gigi behel tidak perih', 'Gel pelindung sariawan dengan ekstrak lidah buaya yang membentuk lapisan pelindung sehingga tidak perih saat makan.', 'Oleskan 1-2 tetes gel hingga menutupi seluruh luka sariawan, 3-4 kali sehari.', 'Biarkan mengering 2 menit, hindari makan/minum selama 1 jam setelah dioles.', 'Perbanyak konsumsi buah pepaya, jeruk, dan air putih, serta hindari makanan yang terlalu panas dan pedas.', 'Aman digunakan dan tidak menimbulkan rasa perih saat dioles.', 85000, 30),
(69, 'Gom (Borax Glycerine) 8ml', 'Mata, Mulut & THT', 'Obat Bebas', 'sariawan bibir pecah luka dalam mulut perih sariawan murah', 'Cairan oles antiseptik tradisional untuk membantu mengeringkan luka sariawan di bibir dan rongga mulut.', 'Oleskan pada sariawan menggunakan cotton bud 2-3 kali sehari.', 'Pemakaian lokal di rongga mulut.', 'Jaga kebersihan mulut dengan berkumur air putih setiap selesai makan.', 'Jangan ditelan.', 6500, 90),
(70, 'Adem Sari Ching Ku (Sachet)', 'Mata, Mulut & THT', 'Suplemen Herbal', 'panas dalam sariawan bibir pecah pecah tenggorokan kering susah bab', 'Minuman sari penyegar herbal dan vitamin C tinggi untuk meredakan gejala panas dalam, sariawan, dan tenggorokan kering.', 'Larutkan 1 sachet dalam 200 ml air dingin, minum 2 kali sehari.', 'Aduk dan segera minum saat masih berbusa.', 'Kurangi konsumsi gorengan, keripik pedas, dan perbanyak makan sayur berkuah.', 'Hati-hati pada penderita maag sensitif.', 3500, 130),
(71, 'Cooling 5 Semprot Tenggorokan & Mulut 15ml', 'Mata, Mulut & THT', 'Obat Bebas', 'sakit tenggorokan sariawan gusi sakit nyeri mulut semprot praktis', 'Semprotan antiseptik anestesi lokal untuk meredakan sakit tenggorokan, nyeri sariawan, dan iritasi gusi secara instan.', 'Semprotkan 2-3 kali tepat pada area tenggorokan atau sariawan yang sakit setiap 3 jam bila perlu.', 'Semprot rongga mulut.', 'Minum air suhu ruang secara perlahan dan kurangi merokok atau paparan asap.', 'Jangan disemprotkan melebihi dosis anjuran.', 36000, 45),
(72, 'Enkasari Herbal Mouthwash 120ml', 'Mata, Mulut & THT', 'Obat Tradisional', 'sariawan bau mulut penyegar napas gusi berdarah ringan', 'Cairan kumur dari ekstrak daun saga, daun sirih, dan akar kayu manis untuk mencegah sariawan dan menyegarkan mulut.', 'Gunakan 15 ml untuk berkumur 2-3 kali sehari.', 'Kumur selama 30-60 detik lalu buang.', 'Bersihkan sela-sela gigi menggunakan benang gigi (dental floss) agar tidak ada sisa makanan membusuk.', 'Tidak untuk ditelan.', 23000, 55),
(73, 'Cap Burung Kakak Tua Obat Sakit Gigi 2ml', 'Mata, Mulut & THT', 'Obat Bebas', 'sakit gigi berlubang nyeri gigi cenut cenut gusi bengkak', 'Cairan minyak cengkeh pekat untuk meredakan rasa nyeri pada gigi yang berlubang.', 'Jepit kapas kecil dengan pinset, tetesi cairan, lalu selipkan pada lubang gigi yang sakit.', 'Hanya ditempelkan pada lubang gigi.', 'Obat ini meredakan nyeri sementara; setelah nyeri reda, segera periksakan ke dokter gigi untuk ditambal.', 'Usahakan cairan tidak mengenai gusi sehat atau lidah secara berlebihan.', 16000, 60),
(74, 'Listerine Cool Mint 100ml', 'Mata, Mulut & THT', 'Perawatan Mulut', 'bau mulut plak gigi gusi kurang sehat napas kurang segar', 'Antiseptik pencuci mulut untuk mengurangi 99.9% kuman penyebab bau mulut dan plak.', 'Kumur dengan 20 ml selama 30 detik, 2 kali sehari setelah menyikat gigi.', 'Jangan dicampur air dan jangan ditelan.', 'Sikat juga permukaan lidah secara lembut saat menggosok gigi untuk mengangkat bakteri penyebab bau mulut.', 'Tidak untuk anak di bawah 12 tahun.', 13500, 80),
(75, 'Sensodyne Repair & Protect 100g', 'Mata, Mulut & THT', 'Perawatan Gigi', 'gigi ngilu gigi sensitif minum es ngilu makan asam ngilu', 'Pasta gigi khusus untuk membentuk lapisan pelindung pada area gigi yang sensitif dan meredakan rasa ngilu.', 'Gunakan untuk menyikat gigi 2 kali sehari secara teratur.', 'Sikat gigi dengan bulu sikat yang lembut.', 'Hindari menyikat gigi terlalu keras secara horizontal dan batasi minuman bersoda yang mengikis email gigi.', 'Tutup rapat tube setelah digunakan.', 38000, 50),
(76, 'Imboost Tablet (Strip 10 Tablet)', 'Vitamin & Suplemen', 'Suplemen Kesehatan', 'imun turun gampang sakit pemulihan habis sakit gejala flu mulai bersin lemas', 'Suplemen peningkat daya tahan tubuh (imunomodulator) dengan ekstrak Echinacea dan Zinc Picolinate.', 'Dewasa: 1 tablet, 2-3 kali sehari.', 'Sesudah makan.', 'Kombinasikan dengan tidur cukup 7-8 jam, konsumsi makanan tinggi protein (telur, ikan, ayam), dan berjemur matahari pagi 15 menit.', 'Tidak dianjurkan digunakan lebih dari 8 minggu berturut-turut.', 44000, 85),
(77, 'Enervon-C (Strip 4 Tablet)', 'Vitamin & Suplemen', 'Suplemen Kesehatan', 'badan lemas kurang vitamin c sariawan pemulihan sakit begadang tugas kuliah', 'Kombinasi Vitamin C 500mg dan Vitamin B Kompleks untuk menjaga daya tahan tubuh dan membantu metabolisme energi.', 'Dewasa: 1 tablet, 1 kali sehari.', 'Sesudah sarapan pagi.', 'Minum air putih yang cukup (warna urin mungkin menjadi kuning cerah akibat ekskresi vitamin B, hal ini normal).', 'Simpan di tempat kering di bawah suhu 30 derajat Celcius.', 5500, 150),
(78, 'Enervon-C Active (Strip 4 Tablet)', 'Vitamin & Suplemen', 'Suplemen Kesehatan', 'lelah lesu aktivitas padat butuh stamina zinc vitamin c ramah lambung', 'Mengandung Vitamin C Non-Acidic (aman di lambung), Vitamin B Kompleks, dan Zinc untuk menjaga stamina harian.', 'Dewasa: 1 tablet, 1 kali sehari.', 'Sesudah makan.', 'Lakukan peregangan tubuh setiap 1 jam saat belajar/bekerja lama agar aliran oksigen ke otak lancar.', 'Aman untuk lambung sensitif.', 6500, 120),
(79, 'Holisticare Ester C (Strip 4 Tablet)', 'Vitamin & Suplemen', 'Suplemen Kesehatan', 'vitamin c aman untuk maag sariawan daya tahan tubuh kulit sehat', 'Vitamin C dalam bentuk Ester yang memiliki pH netral sehingga tidak perih di lambung dan bertahan lebih lama di tubuh.', 'Dewasa: 1-2 tablet sehari.', 'Sebelum atau sesudah makan.', 'Konsumsi sayur dan buah segar setiap hari sebagai sumber serat dan antioksidan alami.', 'Aman bagi penderita maag.', 8500, 100),
(80, 'CDR (Calcium D Redoxon) Effervescent 10 Tablet', 'Vitamin & Suplemen', 'Suplemen Kesehatan', 'tulang kuat kalsium vitamin c vitamin d badan lemas pemulihan', 'Tablet larut air rasa jeruk segar yang mengandung Kalsium, Vitamin C, D, dan B6 untuk kesehatan tulang dan daya tahan tubuh.', 'Larutkan 1 tablet dalam segelas air dingin (200 ml), minum 1 kali sehari.', 'Sesudah makan.', 'Tunggu hingga tablet benar-benar larut sempurna sebelum diminum.', 'Tutup rapat tube segera setelah mengambil tablet.', 52000, 60),
(81, 'Sangobion Kapsul (Strip 10 Kapsul)', 'Vitamin & Suplemen', 'Suplemen Kesehatan', 'kurang darah anemia pusing berkunang kunang pucat lemas cepat lelah haid banyak', 'Suplemen zat besi (Ferrous Gluconate), Asam Folat, dan Vitamin B12 untuk pembentukan sel darah merah dan mengatasi anemia.', 'Dewasa: 1 kapsul, 1 kali sehari.', 'Pada waktu makan atau sesudah makan.', 'Perbanyak makan bayam, hati ayam, daging merah, dan hindari minum teh/kopi bersamaan dengan suplemen zat besi karena menghambat penyerapan.', 'Dapat menyebabkan feses berwarna gelap/hitam (hal ini normal).', 21000, 95),
(82, 'Neurobion Putih (Strip 10 Tablet)', 'Vitamin & Suplemen', 'Vitamin Neurotropik', 'kesemutan kebas baal jari tangan kaki pegal saraf kekurangan vitamin b', 'Vitamin neurotropik (Vitamin B1, B6, dan B12) untuk menjaga kesehatan fungsi saraf dan mengatasi kesemutan atau kebas.', 'Dewasa: 1 tablet, 1 kali sehari.', 'Sesudah makan.', 'Jangan duduk bersila atau melipat kaki terlalu lama, dan gerakkan pergelangan tangan secara berkala saat mengetik.', 'Telan utuh dengan air putih.', 26000, 80),
(83, 'Neurobion Forte Pink (Strip 10 Tablet)', 'Vitamin & Suplemen', 'Vitamin Neurotropik', 'kesemutan parah saraf kejepit ringan kebas tangan kaki nyeri saraf', 'Mengandung Vitamin B1, B6, dan B12 dosis tinggi (5000 mcg) untuk memperbaiki kerusakan sel saraf tepi penyebab kesemutan.', 'Dewasa: 1 tablet, 1 kali sehari.', 'Sesudah makan.', 'Kompres hangat area yang sering kram/kebas dan kurangi konsumsi gula berlebih.', 'Konsultasikan jika kesemutan tidak membaik setelah 2 minggu.', 48000, 65),
(84, 'Becom-Zet (Strip 10 Kaplet)', 'Vitamin & Suplemen', 'Suplemen Kesehatan', 'pemulihan pasca sakit sariawan lemas masa penyembuhan butuh vitamin lengkap', 'Multivitamin dosis tinggi berisi Vitamin E, Vitamin C 750mg, Vitamin B Kompleks, Asam Folat, dan Zinc untuk mempercepat pemulihan.', 'Dewasa: 1 kaplet, 1 kali sehari.', 'Sesudah makan pagi atau siang.', 'Fokus pada istirahat berkualitas dan makan makanan bergizi seimbang selama masa pemulihan.', 'Minum air putih yang banyak.', 31000, 75),
(85, 'Caviplex (Strip 10 Kaplet)', 'Vitamin & Suplemen', 'Suplemen Kesehatan', 'multivitamin harian lemas kurang nafsu makan suplemen mahasiswa murah lengkap', 'Multivitamin dan mineral lengkap untuk menambah nafsu makan, mengatasi kelelahan, dan memelihara kesehatan tubuh.', 'Dewasa: 1 kaplet, 1 kali sehari.', 'Sesudah makan.', 'Buat jadwal makan yang teratur tiga kali sehari meskipun sedang sibuk mengerjakan tugas.', 'Simpan di tempat sejuk dan kering.', 9500, 110),
(86, 'Pharmaton Formula (Strip 5 Kapsul)', 'Vitamin & Suplemen', 'Suplemen Kesehatan', 'stamina loyo ngantuk terus kurang fokus konsentrasi kerja berat ginseng', 'Kombinasi multivitamin, mineral, dan ekstrak Ginseng G115 terstandar untuk menjaga stamina fisik serta fokus mental.', 'Dewasa: 1 kapsul lunak sehari.', 'Wajib diminum saat sarapan pagi.', 'Lakukan olahraga kardio ringan (jogging/jalan cepat) 20 menit di pagi hari untuk memompa oksigen ke seluruh tubuh.', 'Hindari minum di malam hari karena dapat membuat sulit tidur.', 28500, 55),
(87, 'Curcuma Force (Blister 12 Tablet)', 'Vitamin & Suplemen', 'Suplemen Herbal', 'kurang nafsu makan fungsi hati lemas habis sakit tipes pemulihan', 'Ekstrak temulawak (Curcuma xanthorrhiza) dan Piperin untuk memperbaiki nafsu makan serta memelihara kesehatan fungsi hati.', 'Dewasa: 1-2 tablet, 3 kali sehari.', 'Sesudah makan.', 'Sajikan makanan dalam keadaan hangat dan menarik untuk membangkitkan selera makan.', 'Aman untuk penggunaan pemulihan.', 16500, 70),
(88, 'Prove D3-1000 IU (Strip 10 Tablet)', 'Vitamin & Suplemen', 'Suplemen Kesehatan', 'vitamin d kurang sinar matahari imun tubuh nyeri tulang jarang keluar kamar', 'Suplemen Vitamin D3 1000 IU untuk memenuhi kebutuhan vitamin D harian, menjaga imunitas, dan kesehatan tulang.', 'Dewasa: 1 tablet, 1 kali sehari.', 'Sesudah makan (terutama makanan yang mengandung lemak sehat agar mudah diserap).', 'Usahakan tetap membuka jendela kamar di pagi hari agar sirkulasi udara dan cahaya matahari masuk.', 'Simpan jauh dari jangkauan anak-anak.', 35000, 60),
(89, 'Natur-E 100 IU (16 Kapsul Lunak)', 'Vitamin & Suplemen', 'Suplemen Kesehatan', 'kulit kering kusam antioksidan vitamin e kesehatan kulit', 'Kapsul lunak Vitamin E alami dari minyak biji gandum dan bunga matahari untuk menjaga kelembapan dan elastisitas kulit dari dalam.', '1-3 kapsul lunak sehari.', 'Sesudah makan.', 'Minum 8 gelas air putih sehari dan gunakan pelembap serta sunscreen saat beraktivitas di luar ruangan.', 'Telan kapsul utuh.', 22500, 50),
(90, 'Madu TJ Murni 150g', 'Vitamin & Suplemen', 'Kesehatan Alami', 'daya tahan tubuh batuk ringan sariawan lemas pemanis alami sehat', 'Madu murni pilihan lengkap dengan enzim alami untuk menjaga stamina, meredakan radang tenggorokan, dan mempercepat pemulihan.', '1-2 sendok makan, 3 kali sehari (langsung atau dicampur air hangat).', 'Sebelum atau sesudah makan.', 'Gunakan sendok plastik atau kayu, dan seduh dengan air hangat suam-suam kuku (bukan air mendidih agar nutrisi madu tidak rusak).', 'Jangan diberikan pada bayi di bawah usia 1 tahun.', 23500, 85),
(91, 'Oximeter Pulse Fingertip Digital', 'Alat Kesehatan & P3K', 'Alat Kesehatan', 'cek saturasi oksigen detak jantung sesak napas pantau kesehatan', 'Alat ukur kadar oksigen dalam darah (SpO2) dan denyut nadi secara cepat dan akurat melalui ujung jari.', 'Jepitkan pada ujung jari telunjuk dalam posisi rileks selama 10 detik.', 'Pemakaian luar.', 'Jika saturasi oksigen di bawah 95% disertai sesak napas, duduklah dengan posisi sedikit membungkuk ke depan dan segera cari bantuan medis.', 'Pastikan jari tidak basah atau memakai kuteks tebal saat mengukur.', 85000, 20),
(92, 'Termometer Digital Flexi / Kaku', 'Alat Kesehatan & P3K', 'Alat Kesehatan', 'ukur suhu badan cek demam panas tinggi anak dewasa', 'Termometer digital akurat dengan bunyi indikator otomatis untuk memantau suhu tubuh saat demam.', 'Jepitkan ujung sensor di tengah ketiak selama 1-2 menit hingga berbunyi bip.', 'Pemakaian luar.', 'Suhu tubuh normal berkisar antara 36,5 - 37,2 derajat Celcius; catat suhu secara berkala untuk memantau perkembangan demam.', 'Bersihkan ujung sensor dengan kapas alkohol sebelum dan sesudah dipakai.', 32000, 26),
(93, 'Rivanol Cairan Antiseptik 100ml', 'Alat Kesehatan & P3K', 'Obat Bebas', 'kompres luka cuci luka bernanah luka lecet kotor tidak perih', 'Cairan antiseptik untuk membersihkan dan mengompres luka terbuka, luka lecet, atau bisul tanpa menimbulkan rasa perih.', 'Tuangkan pada kasa steril, lalu usapkan atau kompreskan pada luka.', 'Pemakaian luar.', 'Ganti kasa penutup luka minimal 2 kali sehari agar luka tetap bersih dan cepat kering.', 'Simpan di tempat terlindung dari cahaya matahari langsung.', 7500, 70),
(94, 'Kasa Steril Husada (Kotak 16 Lembar)', 'Alat Kesehatan & P3K', 'Alat Kesehatan', 'tutup luka kompres luka perban luka jatuh operasi', 'Kain kasa hidrofil steril berdaya serap tinggi untuk membersihkan dan menutup luka agar terhindar dari kontaminasi bakteri.', 'Buka kemasan, ambil kasa secukupnya untuk menutup luka lalu rekatkan dengan plester.', 'Sekali pakai.', 'Cuci tangan dengan sabun sebelum melakukan perawatan luka.', 'Jangan gunakan jika kemasan bagian dalam sudah rusak.', 9500, 100),
(95, 'Alkohol Swab Sensi / OneMed (Per Kotak 100 Pcs)', 'Alat Kesehatan & P3K', 'Alat Kesehatan', 'bersihkan alat sterilkan termometer antiseptik kulit luar', 'Tisu kapas beralkohol 70% dalam kemasan satuan untuk membersihkan permukaan kulit yang utuh atau mensterilkan alat kesehatan.', 'Buka sachet dan usapkan pada area yang ingin dibersihkan.', 'Pemakaian luar.', 'Jangan gunakan alkohol langsung pada luka terbuka yang lecet karena akan sangat perih dan merusak jaringan baru; gunakan cairan NaCl/Rivanol untuk luka terbuka.', 'Mudah terbakar, jauhkan dari api.', 15000, 60),
(96, 'Masker Medis 3 Ply Earloop (Isi 50 Pcs)', 'Alat Kesehatan & P3K', 'Alat Kesehatan', 'batuk pilek pelindung debu polusi jalan raya cegah penularan flu', 'Masker bedah 3 lapis dengan efisiensi filtrasi bakteri tinggi untuk melindungi saluran napas dari debu, polusi, dan droplet virus.', 'Gunakan menutupi hidung hingga dagu, ganti masker setiap 4-6 jam atau jika lembap.', 'Pemakaian luar.', 'Tekan kawat penyangga di bagian hidung agar masker menutup rapat tanpa celah.', 'Buang ke tempat sampah tertutup setelah digunakan.', 25000, 90),
(97, 'Minyak Telon Plus My Baby Eucalyptus 90ml', 'Alat Kesehatan & P3K', 'Obat Tradisional', 'perut kembung hangat lembut anti nyamuk kulit sensitif', 'Minyak telon dengan kehangatan lembut dan perlindungan dari gigitan nyamuk hingga 8 jam, cocok untuk anak maupun dewasa berkulit sensitif.', 'Oleskan 5-10 tetes pada dada, perut, pinggang, dan telapak kaki.', 'Sehabis mandi dan sebelum tidur.', 'Gunakan pakaian tidur yang nyaman dan atur suhu kamar pada kisaran 24-26 derajat Celcius.', 'Hanya untuk pemakaian luar.', 24500, 32),
(98, 'Balsem Otot Geliga 20g', 'Alat Kesehatan & P3K', 'Obat Bebas', 'nyeri otot keseleo punggung pegal pemanasan olahraga memar', 'Balsem otot hangat yang diformulasikan khusus untuk meredakan nyeri otot, pukulan, memar, dan keseleo.', 'Oleskan dan pijat perlahan pada bagian yang sakit.', 'Pemakaian luar.', 'Lakukan pemanasan dan pendinginan yang cukup sebelum serta sesudah berolahraga.', 'Jangan digunakan di area wajah atau kulit sensitif.', 11500, 75),
(99, 'Ambeven Kapsul (Strip 10 Kapsul)', 'Alat Kesehatan & P3K', 'Obat Tradisional', 'wasir ambeien benjolan anus bab berdarah nyeri duduk', 'Kapsul herbal dari ekstrak daun ungu (Graptophyllum pictum) untuk membantu meringankan gejala wasir/ambeien seperti bengkak dan nyeri.', 'Dewasa: 2 kapsul, 3 kali sehari.', 'Sesudah makan.', 'Perbanyak makan pepaya dan sayur, jangan mengejan terlalu keras atau duduk terlalu lama di kloset sambil bermain HP.', 'Kurangi makanan pedas dan daging olahan.', 21500, 50),
(100, 'Kejibeling Kapsul Herbal (Strip 10 Kapsul)', 'Alat Kesehatan & P3K', 'Obat Tradisional', 'anyang anyangan susah buang air kecil nyeri kencing pinggang pegal batu ginjal ringan', 'Ekstrak daun kejibeling, kumis kucing, dan tempuyung untuk membantu melancarkan buang air kecil (BAK).', 'Dewasa: 2 kapsul, 2-3 kali sehari.', 'Sesudah makan.', 'Minum air putih minimal 2,5 liter sehari dan jangan pernah menahan keinginan buang air kecil.', 'Jika nyeri BAK disertai demam atau urin kemerahan, segera ke dokter.', 12000, 60);
INSERT INTO `obat` (`id`, `nama_obat`, `kategori`, `golongan`, `gejala_keyword`, `indikasi`, `dosis`, `aturan_pakai`, `saran_sembuh`, `peringatan`, `harga`, `stok`) VALUES
(101, 'Lelap Kaplet Herbal (Strip 4 Kaplet)', 'Alat Kesehatan & P3K', 'Obat Tradisional', 'susah tidur insomnia gelisah tidur tidak nyenyak begadang terus', 'Herbal alami dari ekstrak biji pala dan akar valerian untuk membantu meningkatkan kualitas tidur secara alami.', 'Dewasa: 1-2 kaplet diminum 30-60 menit sebelum tidur malam.', 'Malam hari sebelum tidur.', 'Matikan layar HP/laptop 1 jam sebelum tidur, redupkan lampu kamar, dan hindari minum kopi atau teh setelah jam 4 sore.', 'Jangan mengemudi atau mengoperasikan mesin setelah minum obat ini.', 11500, 65),
(102, 'Komix Herbal Original (Pack 4 Tube)', 'Batuk & Flu', 'Obat Tradisional', 'batuk berdahak tenggorokan gatal masuk angin batuk herbal praktis', 'Obat batuk herbal cair dengan ekstrak daun lagundi, jahe merah, thymi, dan madu untuk meredakan batuk berdahak dan menghangatkan tenggorokan.', 'Dewasa: 1 tube, 3 kali sehari.', 'Sesudah makan, kocok dahulu.', 'Minum air hangat setelah mengonsumsi obat ini untuk membantu meluruhkan lendir di tenggorokan.', 'Simpan di tempat sejuk.', 10500, 93),
(103, 'Laserin Sirup Herbal 60ml', 'Batuk & Flu', 'Obat Tradisional', 'batuk masuk angin muntah mual sesak napas ringan melegakan tenggorokan', 'Sirup herbal tradisional dari jahe, cengkeh, daun sirih, dan kayu manis untuk meredakan batuk, masuk angin, serta melegakan pernapasan.', 'Dewasa: 1-2 sendok makan, 3 kali sehari.', 'Sesudah makan.', 'Istirahat di ruangan dengan sirkulasi udara bersih dan hindari kipas angin yang mengarah langsung ke tubuh.', 'Kocok botol sebelum diminum.', 14500, 70),
(104, 'Salonpas Jet Spray 60ml', 'Demam & Nyeri', 'Obat Bebas', 'kram otot olahraga keseleo mendadak nyeri pergelangan kaki lutut futsal lari', 'Semprotan pereda nyeri otot dan sendi instan yang praktis digunakan saat berolahraga atau mengalami kram mendadak.', 'Kocok kaleng dan semprotkan dari jarak 10 cm pada area yang nyeri selama 3-5 detik.', 'Pemakaian luar.', 'Kompres dengan es (metode RICE: Rest, Ice, Compression, Elevation) jika terjadi pembengkakan pada pergelangan kaki.', 'Jangan disemprotkan pada luka terbuka atau dihirup.', 55000, 0),
(105, 'Rohto Eye Flush Pencuci Mata 150ml', 'Mata, Mulut & THT', 'Alat Kesehatan', 'cuci mata kelilipan debu kotoran masuk mata mata gatal lelah', 'Cairan pencuci mata steril yang dilengkapi cangkir khusus (eye bath) untuk membersihkan mata dari debu, kotoran, atau sisa kosmetik.', 'Tuang 5 ml cairan ke dalam eye cup, tempelkan ke mata sambil menunduk, lalu kedip-kedipkan mata selama 30 detik.', 'Pemakaian luar pada mata.', 'Cuci bersih eye cup dengan air matang sebelum dan sesudah digunakan untuk mata kiri dan kanan.', 'Lepaskan lensa kontak sebelum mencuci mata.', 37000, 25);
